from pathlib import Path
import importlib.util

generator_path = Path(__file__).resolve().parent / 'generate-editorial-articles.py'
spec = importlib.util.spec_from_file_location('editorial_generator', generator_path)
generator = importlib.util.module_from_spec(spec)
spec.loader.exec_module(generator)
article_html = generator.article_html

extra = [
    dict(slug='inflation-adjusted-value-and-purchasing-power', title='Inflation-Adjusted Value: Understand Future Purchasing Power', desc='Learn how inflation changes the purchasing power of money and how to compare nominal and inflation-adjusted values with a transparent estimate.', question='A future amount can be larger in rupees and still buy less than the same amount today. Inflation-adjusted analysis separates the number printed on an account from what that number may purchase.', formula='Future nominal value = present value × (1 + inflation rate) raised to the number of years. Real value can be estimated by dividing a nominal amount by the accumulated inflation factor.', example='At 6% annual inflation, ₹1,00,000 of today’s purchasing power would require about ₹1,33,823 after five years in a simplified constant-rate illustration.', calc='inflation-calculator.html', context='Inflation varies by basket, location and household. A general calculator does not predict the price of a particular rent, school fee, medicine or product.', practice='Use a range of inflation assumptions and identify the spending basket behind the rate. Compare nominal investment returns with inflation rather than looking only at the rupee balance.', mistakes='Do not subtract an inflation percentage from a future amount without considering compounding. Do not treat one published index as the exact personal inflation rate for every household.', related=[('Inflation Calculator','inflation-calculator.html'),('SIP and Inflation Guide','/blog/sip-inflation-real-returns-explained.html')]),
    dict(slug='loan-to-value-ratio-explained', title='Loan-to-Value Ratio: How LTV Is Calculated and Read', desc='Understand loan-to-value ratio, the value used in the denominator, and why LTV affects borrowing risk without deciding loan approval.', question='Loan-to-value ratio compares a loan amount with the value of the asset offered as security. It is a risk and affordability measure, not a promise that a lender will approve a particular application.', formula='LTV = loan amount ÷ appraised property or asset value × 100.', example='A ₹40 lakh loan against an appraised value of ₹50 lakh has an LTV of 80%. A change in valuation or loan amount changes the ratio even if the borrower’s income is unchanged.', calc='loan-to-value-calculator.html', context='Lenders may use their own valuation, product caps, margin rules, insurance requirements, fees and eligibility checks. Market price and lender-accepted value are not always the same.', practice='Keep the valuation date, asset type and loan purpose with the result. Compare LTV with EMI affordability, total interest, liquidity and the risk of a valuation change.', mistakes='Using a listing price instead of an accepted valuation can overstate borrowing capacity. Do not confuse LTV with interest rate, debt-to-income ratio or the down payment alone.', related=[('Loan-to-Value Calculator','loan-to-value-calculator.html'),('Loan EMI Calculator','loan-emi-calculator.html')]),
]
for t in extra:
    (Path(__file__).resolve().parents[1] / 'blog' / f"{t['slug']}.html").write_text(article_html(t), encoding='utf-8')
print('added', len(extra))
